// The studio's effect library: tested GLSL looks, finishing passes, light, atmosphere, particles,
// camera moves and themed pieces. Opus (and the owner) use them by name with a few parameters
// ({"op":"look"} / {"op":"fx"}), so an edit gets a strong, reliable finish without writing shader code;
// custom code stays available for the signature moments. Each preset's code is plain effect code
// (the same safe subset Opus writes), generated by substituting the parameters as literals.
import { BlendMode } from '../state/types';
import { hexToRgb } from './compositor';

export type FxGroup = 'look' | 'finish' | 'light' | 'atmosphere' | 'particles' | 'camera' | 'beat' | 'themed';
export interface FxNum { id: string; label: string; def: number; min: number; max: number }
export interface FxColor { id: string; label: string; color: string }
export type FxParam = FxNum | FxColor;
export interface FxDef {
  id: string;
  name: string;
  group: FxGroup;
  hint: string;
  blend: BlendMode;
  /** Typical length in seconds when placed. */
  dur: number;
  params: FxParam[];
  code: string;
  /** Reads an anchor point (transform x/y or "at"). */
  anchor?: boolean;
  /** Reacts to the music's beats. */
  beat?: boolean;
  /** A look already used in an approved edit (the style bank): don't repeat it as the main look. */
  usedIn?: string;
}

const n = (id: string, label: string, def: number, min = 0, max = 1): FxNum => ({ id, label, def, min, max });
const col = (id: string, label: string, color: string): FxColor => ({ id, label, color });
const GRAIN = n('grain', 'Grain', 0.3), VIG = n('vignette', 'Vignette', 0.4), HALO = n('halation', 'Halation', 0.2), SHARP = n('sharpen', 'Sharpen', 0.25, 0, 0.8);
const FIN = [GRAIN, VIG, HALO, SHARP];

