// every look gets an exposure control applied to the picture before its grade, so dim footage is lifted
// inside the look rather than crushed by it
for (const d of FX_LIBRARY) {
  if (d.group !== 'look' || d.params.some(q => q.id === 'exposure') || !d.code.includes('sharpenFrame(uv, $sharpen)')) continue;
  d.params.push(n('exposure', 'Exposure', 0, -0.3, 0.3));
  d.code = d.code.replace('sharpenFrame(uv, $sharpen)', 'liftExposure(sharpenFrame(uv, $sharpen), $exposure)');
}

const BY_ID = new Map(FX_LIBRARY.map(d => [d.id, d]));
export const getFx = (id: string) => BY_ID.get(id);
export const isColorParam = (p: FxParam): p is FxColor => 'color' in p;

const lit = (v: number) => { const s = (Math.round(v * 10000) / 10000).toString(); return s.includes('.') || s.includes('e') ? s : `${s}.0`; };
const vec3Of = (hex: string) => { const [r, g, b] = hexToRgb(hex); return `vec3(${lit(r)}, ${lit(g)}, ${lit(b)})`; };

/** Parameter values with defaults filled in and numbers clamped. */
export function fxParams(def: FxDef, raw?: Record<string, unknown>): Record<string, number | string> {
  const out: Record<string, number | string> = {};
  for (const p of def.params) {
    const v = raw?.[p.id];
    if (isColorParam(p)) out[p.id] = typeof v === 'string' && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(v) ? v : p.color;
    else { const x = Number(v); out[p.id] = Number.isFinite(x) && v !== null && v !== '' ? Math.min(p.max, Math.max(p.min, x)) : p.def; }
  }
  return out;
}

/** The effect code for a preset with these parameters. */
export function fxCode(def: FxDef, params: Record<string, number | string>): string {
  return def.code.replace(/\$(\w+)/g, (m, id) => {
    const p = def.params.find(x => x.id === id);
    if (!p) return m;
    const v = params[id];
    return isColorParam(p) ? vec3Of(typeof v === 'string' ? v : p.color) : lit(typeof v === 'number' ? v : p.def);
  });
}

/** One line per preset for Opus: name, what it does, its parameters with defaults. */
export function fxCatalogText(): string {
  const groups: Record<FxGroup, string> = { look: 'LOOKS', finish: 'FINISH', light: 'LIGHT', atmosphere: 'ATMOSPHERE', particles: 'PARTICLES', camera: 'CAMERA AND IMPACT', beat: 'BEAT MOMENTS', themed: 'THEMED' };
  const out: string[] = [];
  for (const g of Object.keys(groups) as FxGroup[]) {
    const items = FX_LIBRARY.filter(d => d.group === g);
    if (!items.length) continue;
    out.push(`  ${groups[g]}:`);
    for (const d of items) {
      const ps = d.params.map(p => (isColorParam(p) ? `${p.id} "${p.color}"` : `${p.id} ${lit(p.def).replace(/\.0$/, '')}`)).join(', ');
      out.push(`  - ${d.id}${d.usedIn ? ` (used in ${d.usedIn})` : ''}${d.anchor ? ' [anchor]' : ''}${d.beat ? ' [beat]' : ''} ${d.blend !== 'normal' ? `(${d.blend}) ` : ''}${d.hint}${ps ? ` Params: ${ps}.` : ''}`);
    }
  }
  return out.join('\n');
}
